Definition bcp_safety_wit_1 :=
forall (cap: Z) (live: Z) (n: Z) (row_table: Z) (unassigned: Z) (true_counts: Z) (states: Z) (levels: Z) (reasons: Z) (values: Z) (logical_dl: Z) (ranks: (Z -> (@option nat))) (snap: dense_snapshot) (original_count: Z) (F: cnf) (s_pre: Z) (PreH1 : (0 <= n)) (PreH2 : (n < INT_MAX)) (PreH3 : (0 <= original_count)) (PreH4 : (original_count <= live)) (PreH5 : (0 <= live)) (PreH6 : (live <= cap)) (PreH7 : (coherent_snapshot F n live original_count snap )) (PreH8 : (stable_search_facts n snap ranks logical_dl )) (PreH9 : (bcp_ready (cdcl_view_of_snapshot (n) (snap) (ranks) (logical_dl)) )),
  ((( &( "unitcl" ) )) # Int  |->_)
  **  ((( &( "s" ) )) # Ptr  |-> s_pre)
  **  (solver_state s_pre values reasons levels states true_counts unassigned row_table n live cap logical_dl snap )
|--
  “ (1 <> (INT_MIN)) ”
.

